function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const O = '#0d0a08', G = '#d4a017', GL = '#f0d060', GD = '#a07810';
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };
  const cx = 32, cy = 32, R = 22;
  for (let y = 8; y < 56; y++) for (let x = 8; x < 56; x++) {
    const dx = x - cx, dy = y - cy, r2 = dx * dx + dy * dy;
    if (r2 <= (R - 1) * (R - 1)) {
      let c = G;
      if (dx + dy < -6) c = GL;
      else if (dx + dy > 8) c = GD;
      px(x, y, 1, 1, c);
    }
    if (r2 >= (R - 2) * (R - 2) && r2 <= R * R) px(x, y, 1, 1, O);
  }
  px(30, 22, 4, 20, GL); px(22, 30, 20, 4, GL);
  px(31, 24, 2, 16, O); px(24, 31, 16, 2, O);
  px(28, 28, 8, 8, GD);
}
